// Short reflections on prayer, shown at the bottom of the Prayer List page
// and at the end of a prayer (prayer.js): a random one each time the page
// loads, then swipe (or tap ‹ ›) to browse the rest in order.
//
// Generated from "Prayer App 150 Reflections and 8 Categories.xlsx"
// (Reflections sheet: Final Reflection, Attribution, Teaching Collection).
// Each is an adapted reflection, not a verbatim quotation — hence
// "Adapted from …" in `source`. `id` is the sheet's ID column — keep it
// unique and never reuse one, since hidden reflections are remembered by id
// (see "Hide" in prayer.js). Edit or add entries freely; keep each to about
// 100 words or fewer.
export const PRAYER_QUOTES = [
  {"id": 1, "text": "Prayer can reveal the strength of our relationship with the Father. Do we turn to Him only when we need help, or do we regularly bring Him our thoughts, thanks and concerns? A close relationship grows through frequent, sincere communication.", "source": "Adapted from David Bailey — Talking with God", "topic": "Relationship with God"},
  {"id": 2, "text": "God's providence can bring comfort and assurance, but we should be careful about interpreting events. We may recognize His care without claiming to know exactly how He has acted. Prayer calls for trust in God's wisdom, not certainty about the meaning of every circumstance.", "source": "Adapted from David Bailey — Talking with God", "topic": "Relationship with God"},
  {"id": 3, "text": "When praying with others, we usually speak aloud; when alone, many of us pray silently. Yet speaking our private prayers aloud can help clarify our thoughts and make our words more deliberate. It may also help us stay focused.", "source": "Adapted from John H. Morris — The Path of Prayer", "topic": "Relationship with God"},
  {"id": 4, "text": "Prayer and meditation belong together. Meditation helps us reflect on God, His Word and our relationship with Him; prayer gives us a way to respond. Both can deepen our awareness of God in daily life.", "source": "Adapted from David Bailey — Talking with God", "topic": "Relationship with God"},
  {"id": 5, "text": "In the Lord's Prayer, Jesus first teaches us to honor God's name, seek His Kingdom and desire His will. He then turns to our daily needs, forgiveness and deliverance. Our Heavenly Father knows what we need before we ask, yet He welcomes our requests. Prayer expresses that trusting dependence.", "source": "Adapted from David Bailey — Talking with God", "topic": "Relationship with God"},
  {"id": 6, "text": "Making room for God in a busy life means recognizing the things that compete for our attention. If we want a stronger relationship with Him and a more consistent habit of prayer, we must deliberately make time to pray.", "source": "Adapted from David Bailey — Talking with God", "topic": "Relationship with God"},
  {"id": 7, "text": "When we long for reassurance that God is with us, we may be tempted to treat an unusual experience as a personal sign. Faith calls us to trust what God has revealed in Scripture rather than rely on speculation about events we cannot explain.", "source": "Adapted from David Bailey — Talking with God", "topic": "Relationship with God"},
  {"id": 8, "text": "When there is tension at home or in the ecclesia, we may hesitate to bring our disagreements before God. Yet there is nothing we cannot bring to Him in prayer. Even when attempts at reconciliation have failed, we should seek His help with humility and a sincere desire to make peace. Prayer should be our first response, not our last resort.", "source": "Adapted from John H. Morris — The Path of Prayer", "topic": "Relationship with God"},
  {"id": 9, "text": "Learning the principles of prayer is not enough; we must put them into practice. Bible reading and prayer support one another. Through His Word God speaks to us, and in prayer we respond to Him.", "source": "Adapted from H. P. Mansfield — Making Prayer Powerful", "topic": "Relationship with God"},
  {"id": 10, "text": "As a loving Father, God may withhold things we think we want because He knows they would not be good for us. Sometimes we ask for things we would be better without. Trusting His wisdom matters as much as presenting our requests.", "source": "Adapted from John H. Morris — The Path of Prayer", "topic": "Relationship with God"},
  {"id": 11, "text": "A Bible reading can give us more than information: it can suggest what to praise, confess or ask of God. When a passage reveals His character or challenges our conduct, we can respond with a thoughtful prayer shaped by what we have learned.", "source": "Adapted from David Bailey — Talking with God", "topic": "Relationship with God"},
  {"id": 12, "text": "We do not always deliberately reject God; sometimes we gradually crowd Him out with everyday concerns. As our awareness of Him fades, our prayers suffer too. The spiritual encouragement of a Bible school or a meaningful meeting needs to carry over into ordinary life.", "source": "Adapted from David Bailey — Talking with God", "topic": "Relationship with God"},
  {"id": 13, "text": "Prayer gives us fellowship with God now, while Scripture points forward to something greater. Revelation 21:3 describes God dwelling with His people. Our prayers today can deepen our longing for the fuller fellowship promised in His Kingdom.", "source": "Adapted from John H. Morris — The Path of Prayer", "topic": "Relationship with God"},
  {"id": 14, "text": "We can turn to God at any time—not only during scheduled devotion. A walk, a quiet moment at work or a pause during recreation can become an opportunity to praise Him, give thanks or ask for help.", "source": "Adapted from H. P. Mansfield — Making Prayer Powerful", "topic": "Relationship with God"},
  {"id": 15, "text": "Our relationship with God is rooted in His covenant through Jesus Christ. God initiated that covenant and showed His desire to draw people near to Him. Prayer is not an attempt to reach a distant stranger; it belongs to the relationship He has made possible.", "source": "Adapted from David Bailey — Talking with God", "topic": "Relationship with God"},
  {"id": 16, "text": "Some of our habits in prayer come from what we have always heard or done. Yet our understanding of why we pray, what we ask for and how we speak to God should be shaped by Scripture, not by routines we have never examined.", "source": "Adapted from David Bailey — Talking with God", "topic": "Privilege and purpose"},
  {"id": 17, "text": "Jesus constantly depended on his Father as he carried out God's purpose. The apostles also prayed as they served, knowing they could not accomplish their work by their own strength. Prayer expresses our dependence on God and our desire to take part in His purpose. It is not a substitute for action, but part of faithful service.", "source": "Adapted from David Bailey — Talking with God", "topic": "Privilege and purpose"},
  {"id": 18, "text": "Prayer need not always be expressed in polished words. Job spoke of tears before God, and David said God heard his weeping. When grief leaves us unable to form a sentence, we can still turn to Him honestly.", "source": "Adapted from David Bailey — Talking with God", "topic": "Privilege and purpose"},
  {"id": 19, "text": "Paul urges believers to pray for rulers and those in authority so that we may live quiet and peaceable lives. Such prayers are not merely political wishes: peaceful conditions can give believers freedom to serve God and share the Gospel.", "source": "Adapted from David Bailey — Talking with God", "topic": "Intercession and community"},
  {"id": 20, "text": "We approach God aware of our weakness, but also grateful for the privilege of speaking to Him. Our need for help is not a reason to stay away; it is a reason to turn to Him with humility and confidence.", "source": "Adapted from John H. Morris — The Path of Prayer", "topic": "Privilege and purpose"},
  {"id": 21, "text": "When we honestly compare our lives with the commandments and perfect example of Christ, we become aware of our shortcomings. That recognition should lead us to humility and repentance, giving greater sincerity to our prayers for mercy and help.", "source": "Adapted from H. P. Mansfield — Making Prayer Powerful", "topic": "Privilege and purpose"},
  {"id": 22, "text": "God desires His children to come to Him in prayer. Remembering that invitation can change our attitude toward prayer: it is a privilege to be welcomed into His presence, not merely another task to complete.", "source": "Adapted from John H. Morris — The Path of Prayer", "topic": "Privilege and purpose"},
  {"id": 23, "text": "Jesus taught his disciples to address God as their Father. Like children who depend upon a loving parent, we can speak to Him openly while trusting His wisdom to grant or withhold what we ask. This is both a privilege and a responsibility.", "source": "Adapted from H. P. Mansfield — Making Prayer Powerful", "topic": "Privilege and purpose"},
  {"id": 24, "text": "Prayer is not an empty ritual; it is our opportunity to speak to the living God. Because we depend on Him, we should bring Him our plans and decisions rather than turn to Him only when things go wrong.", "source": "Adapted from David Bailey — Talking with God", "topic": "Privilege and purpose"},
  {"id": 25, "text": "Prayer can comfort us, calm our minds and strengthen faith, but these benefits are not its only purpose. Prayer is directed toward God Himself. We speak to Him because we depend on Him and desire fellowship with Him, not merely because prayer makes us feel better.", "source": "Adapted from David Bailey — Talking with God", "topic": "Privilege and purpose"},
  {"id": 26, "text": "The desire to pray can fade when it is neglected and return sharply during a crisis. Regular prayer helps keep our relationship with God alive. His Word also gives direction to our prayers, teaching us what deserves our attention.", "source": "Adapted from Melva Purkis and Cyril Tennant — Prayer: Studies in Principle and Practice", "topic": "Privilege and purpose"},
  {"id": 27, "text": "Jesus prayed at decisive moments of his ministry, during the Last Supper, in Gethsemane and on the cross. He also prayed for his disciples. His example shows how prayer can remain central even amid demanding work and profound suffering.", "source": "Adapted from John H. Morris — The Path of Prayer", "topic": "Privilege and purpose"},
  {"id": 28, "text": "God's purpose does not depend on our strength, but we can miss opportunities to serve when we fail to respond. Prayer should strengthen our commitment to faithful action, not become an excuse for avoiding it.", "source": "Adapted from Melva Purkis and Cyril Tennant — Prayer: Studies in Principle and Practice", "topic": "Privilege and purpose"},
  {"id": 29, "text": "We may bring every genuine concern before God, but our requests should be shaped by His purpose and will. Prayer is an expression of trust, not a demand that our preferences be satisfied.", "source": "Adapted from David Bailey — Talking with God", "topic": "Faith and God's Will"},
  {"id": 30, "text": "Christ does more than understand our weakness and our inability to express ourselves perfectly. As our intercessor and mediator, he acts on behalf of those who approach the Father through him. His work gives us confidence to pray.", "source": "Adapted from David Bailey — Talking with God", "topic": "Privilege and purpose"},
  {"id": 31, "text": "Prayer is not only about asking for things. Scripture includes prayers of praise and thanksgiving, reminding us that prayer is also an opportunity to honor God, recognize His goodness and express our desire for His purpose to be fulfilled.", "source": "Adapted from David Bailey — Talking with God", "topic": "Praise and thanksgiving"},
  {"id": 32, "text": "Prayer involves more than asking God for favors. It includes praise, thanksgiving, confession, worship and meditation. In each of these, we acknowledge who God is and seek to draw near to Him.", "source": "Adapted from John H. Morris — The Path of Prayer", "topic": "Praise and thanksgiving"},
  {"id": 33, "text": "Jesus gave the Lord's Prayer as a pattern of priorities. It begins with the Father's name, Kingdom and will, then turns to daily provision, forgiveness and deliverance. Those themes should shape not only our words but also the way we live.", "source": "Adapted from John H. Morris — The Path of Prayer", "topic": "Praise and thanksgiving"},
  {"id": 34, "text": "Remembering God's past goodness gives us reasons for thanksgiving today. When we pray, we can recall particular occasions when He provided, guided or comforted us, and allow those memories to deepen our praise.", "source": "Adapted from H. P. Mansfield — Making Prayer Powerful", "topic": "Praise and thanksgiving"},
  {"id": 35, "text": "David's prayers express longing, sorrow, frustration, joy and thanksgiving. His Psalms remind us that prayer is not limited to one emotional state. We can bring our real feelings before God while lifting our eyes to His greatness.", "source": "Adapted from Melva Purkis and Cyril Tennant — Prayer: Studies in Principle and Practice", "topic": "Praise and thanksgiving"},
  {"id": 36, "text": "God welcomes the praise and thanksgiving of His children. We do not need impressive words. We need to recognize His goodness and express our gratitude sincerely, with attention to the blessings we are acknowledging.", "source": "Adapted from Greg Palmer — Thoughts on the Lord’s Prayer", "topic": "Praise and thanksgiving"},
  {"id": 37, "text": "Paul repeatedly asked God to remove the 'thorn in his flesh,' yet the difficulty remained. Prayer does not guarantee that God will remove every hardship. Sometimes His answer is to sustain us through a trial rather than take it away.", "source": "Adapted from Greg Palmer — Thoughts on the Lord’s Prayer", "topic": "Trials and unanswered prayer"},
  {"id": 38, "text": "To worship is to recognize God's worth. In prayer, we do this by praising His character, acknowledging our dependence and giving Him our attention. Worship is more than speaking respectfully; it reveals what we value most.", "source": "Adapted from H. P. Mansfield — Making Prayer Powerful", "topic": "Praise and thanksgiving"},
  {"id": 39, "text": "Jesus taught the Samaritan woman that true worship must be offered in spirit and truth (John 4:22–24). Sincere prayer is not directed to a god of our own imagining; it grows from knowing the God revealed in Scripture.", "source": "Adapted from David Bailey — Talking with God", "topic": "Praise and thanksgiving"},
  {"id": 40, "text": "David was active in God's service, yet prayer remained central to his life. Jesus is the greatest example: the demands of his ministry did not displace prayer. They made his dependence on the Father all the more evident.", "source": "Adapted from Melva Purkis and Cyril Tennant — Prayer: Studies in Principle and Practice", "topic": "Consistency and time"},
  {"id": 41, "text": "The demands of daily life, material comfort and self-satisfaction can make us feel independent of God. As that attitude grows, prayer becomes secondary. We need to recognize how easily ordinary blessings can distract us from the One who provides them.", "source": "Adapted from H. P. Mansfield — Making Prayer Powerful", "topic": "Praise and thanksgiving"},
  {"id": 42, "text": "Honoring God's name involves more than avoiding disrespectful words. We can praise Him in speech and worship, but true reverence must also shape our attitudes and conduct. Our lives should reflect the character of the God we honor.", "source": "Adapted from Greg Palmer — Thoughts on the Lord’s Prayer", "topic": "Praise and thanksgiving"},
  {"id": 43, "text": "Counting our blessings helps turn prayer toward thanksgiving. As we reflect on what God has provided, we become more conscious of His care and more ready to respond with sincere praise.", "source": "Adapted from H. P. Mansfield — Making Prayer Powerful", "topic": "Praise and thanksgiving"},
  {"id": 44, "text": "Leading an ecclesia in prayer is not primarily a matter of speaking well in public. It requires knowing the congregation, understanding its differing needs and helping everyone approach God together. The aim is to represent the ecclesia faithfully, not impress it.", "source": "Adapted from John H. Morris — The Path of Prayer", "topic": "Intercession and community"},
  {"id": 45, "text": "Giving thanks before a meal should be more than a routine. Jesus taught us to seek first God's Kingdom and to trust Him for our daily needs. We do not need a longer blessing; we need to pause and recognize the care that has provided our food.", "source": "Adapted from David Bailey — Talking with God", "topic": "Praise and thanksgiving"},
  {"id": 46, "text": "Faith is foundational to prayer. We approach God believing that He exists and hears those who seek Him. This confidence should shape our habits: making time to pray, turning to Him in sudden need and remembering His presence throughout the day.", "source": "Adapted from David Bailey — Talking with God", "topic": "Faith and God's Will"},
  {"id": 47, "text": "After his sin, David appealed to God's mercy in Psalm 51. His confidence rested on what God had revealed about Himself: His compassion, lovingkindness and readiness to forgive. Knowing God's character gives substance and hope to our prayers of repentance.", "source": "Adapted from David Bailey — Talking with God", "topic": "Faith and God's Will"},
  {"id": 48, "text": "Prayer rests upon faith in God as Creator and Sustainer, confidence that He has revealed Himself in Scripture, and trust in His care. Without that foundation, even familiar prayers risk becoming little more than words.", "source": "Adapted from Melva Purkis and Cyril Tennant — Prayer: Studies in Principle and Practice", "topic": "Faith and God's Will"},
  {"id": 49, "text": "Knowing God's will and purpose is essential to meaningful prayer. Our requests should be shaped by His Word rather than by human wisdom or personal preference. As Scripture teaches, our confidence rests in asking according to His will.", "source": "Adapted from Melva Purkis and Cyril Tennant — Prayer: Studies in Principle and Practice", "topic": "Faith and God's Will"},
  {"id": 50, "text": "We should not assume that every chance event is a direct act of providence. Yet God can work through ordinary circumstances when His purpose requires it. The challenge is to trust His care without pretending to know exactly how He has acted in every situation.", "source": "Adapted from California Youth Conference 2017 — The Principles and Power of Prayer", "topic": "Faith and God's Will"},
  {"id": 51, "text": "When we say 'Amen,' do we truly mean it? We can examine whether we trust God's promises, believe we may approach Him through Christ and understand what we have just prayed. 'Amen' should express conviction, not merely mark the end of a prayer.", "source": "Adapted from David Bailey — Talking with God", "topic": "Faith and God's Will"},
  {"id": 52, "text": "Faith grows as we hear and reflect upon God's Word. Scripture teaches us His character, purposes and promises, giving us reasons to approach Him confidently through Jesus Christ. Prayer grows deeper when it rests on what God has revealed.", "source": "Adapted from David Bailey — Talking with God", "topic": "Faith and God's Will"},
  {"id": 53, "text": "Elijah prayed earnestly for Israel to recognize the true God, and his prayer on Carmel was answered. Later, in despair, he asked that his life might end, but God instead sustained him. Earnestness matters, yet we cannot dictate how God will answer.", "source": "Adapted from California Youth Conference 2017 — The Principles and Power of Prayer", "topic": "Faith and God's Will"},
  {"id": 54, "text": "Prayer belongs to our present life of faith. Through Christ we approach the Father whom we cannot see, while Scripture points toward a future in which God will dwell with His people. That hope gives our prayers a wider perspective.", "source": "Adapted from John H. Morris — The Path of Prayer", "topic": "Faith and God's Will"},
  {"id": 55, "text": "We need not make a display of emotion to prove that our prayers are sincere. Quiet persistence, honest words and trust in God's wisdom matter more than outward drama. We may keep bringing our requests to Him while accepting His will.", "source": "Adapted from John H. Morris — The Path of Prayer", "topic": "Faith and God's Will"},
  {"id": 56, "text": "Asking God for help is a legitimate and important part of prayer. But whether we ask for ourselves or for someone else, our petitions should be shaped by faith that God knows what is best, even when His answer differs from our wishes.", "source": "Adapted from Melva Purkis and Cyril Tennant — Prayer: Studies in Principle and Practice", "topic": "Faith and God's Will"},
  {"id": 57, "text": "Jesus taught his disciples to seek first God's Kingdom and righteousness. Prayer about these priorities must be followed by a life that reflects them. It is not enough merely to say the right things; we must seek to do the Father's will.", "source": "Adapted from Greg Palmer — Thoughts on the Lord’s Prayer", "topic": "Faith and God's Will"},
  {"id": 58, "text": "A young child may trust a parent's willingness and ability to help. We should develop that same childlike trust in our Heavenly Father, knowing that He hears our prayers and has the wisdom to decide what is best for us.", "source": "Adapted from John H. Morris — The Path of Prayer", "topic": "Faith and God's Will"},
  {"id": 59, "text": "Remember times when you recognized God's care or provision. Reflecting on those experiences can strengthen your trust during a new difficulty, even if you cannot see how it will be resolved. Gratitude for the past can support faith in the present.", "source": "Adapted from Harry Whittaker — Prayer", "topic": "Faith and God's Will"},
  {"id": 60, "text": "Jesus warned against praying in order to be seen by others. Public prayer can easily become a performance, drawing attention to the speaker rather than to God. Its purpose is to express genuine devotion and help others join in prayer.", "source": "Adapted from David Bailey — Talking with God", "topic": "Sincerity and humility"},
  {"id": 61, "text": "When we pray 'Thy Kingdom come,' we express our longing for something still to be fulfilled. The Kingdom is not simply a feeling in our hearts. It is part of God's promised purpose for the earth, and the Lord's Prayer teaches us to look forward to it.", "source": "Adapted from Greg Palmer — Thoughts on the Lord’s Prayer", "topic": "Jesus and the Lord's Prayer"},
  {"id": 62, "text": "To pray 'Thy Kingdom come' meaningfully, we need to understand what we are asking. The first believers longed for the return of Jesus Christ and the establishment of God's Kingdom. That hope should also shape our prayers and priorities.", "source": "Adapted from Greg Palmer — Thoughts on the Lord’s Prayer", "topic": "Jesus and the Lord's Prayer"},
  {"id": 63, "text": "Prayer should spring from sincere motives, without pretence or a desire to impress others. It should also come naturally to us under pressure, rather than being reserved for formal occasions.", "source": "Adapted from California Youth Conference 2017 — The Principles and Power of Prayer", "topic": "Sincerity and humility"},
  {"id": 64, "text": "Jesus revealed the spirit that should shape our prayers. We approach the Father through Christ, seeking to share his trust, humility and obedience. Praying in his name means more than using a phrase; it calls us to reflect his character.", "source": "Adapted from David Bailey — Talking with God", "topic": "Jesus and the Lord's Prayer"},
  {"id": 65, "text": "To hallow God's name means more than pronouncing it respectfully. We honor His name when we recognize His holiness and seek to reflect His character in our own lives. The opening of the Lord's Prayer invites both reverence and self-examination.", "source": "Adapted from Greg Palmer — Thoughts on the Lord’s Prayer", "topic": "Jesus and the Lord's Prayer"},
  {"id": 66, "text": "Jesus taught his disciples to address God as 'Our Father.' Other respectful forms of address may also be appropriate, but these words remind us that we approach Him with the trust, humility and dependence of His children.", "source": "Adapted from Greg Palmer — Thoughts on the Lord’s Prayer", "topic": "Jesus and the Lord's Prayer"},
  {"id": 67, "text": "We approach the Father through Jesus Christ, who gave himself for us and understands our weakness. Taking time to reflect on his character and work can deepen our gratitude and help us pray with greater understanding.", "source": "Adapted from David Bailey — Talking with God", "topic": "Jesus and the Lord's Prayer"},
  {"id": 68, "text": "The disciples asked Jesus to teach them to pray, not merely to give them words to recite. The Lord's Prayer is therefore more than a set formula: it teaches the subjects, priorities and attitudes that should shape our own prayers.", "source": "Adapted from Greg Palmer — Thoughts on the Lord’s Prayer", "topic": "Jesus and the Lord's Prayer"},
  {"id": 69, "text": "Jesus understands human weakness and intercedes for those who approach the Father through him. When words are difficult, we can reflect on his compassion, obedience and love. His example encourages us to keep praying and to become more like him.", "source": "Adapted from John H. Morris — The Path of Prayer", "topic": "Jesus and the Lord's Prayer"},
  {"id": 70, "text": "Jesus spoke to his Father with a constant awareness of God's presence. At Lazarus's tomb, he openly thanked the Father for hearing him. His example encourages us to remember God throughout daily life, not only during set times of prayer.", "source": "Adapted from David Bailey — Talking with God", "topic": "Jesus and the Lord's Prayer"},
  {"id": 71, "text": "The Lord's Prayer is a model for what we should pray about and the attitude we should bring. Its value is not found merely in reciting familiar words. We need to consider what Jesus meant by each request and how those priorities should shape our lives.", "source": "Adapted from Greg Palmer — Thoughts on the Lord’s Prayer", "topic": "Jesus and the Lord's Prayer"},
  {"id": 72, "text": "The Lord's Prayer teaches us how to approach God and what to value. Even its opening words, 'Our Father,' hold together intimacy and reverence. We are invited to draw near to the Creator as children who depend on Him.", "source": "Adapted from H. P. Mansfield — Making Prayer Powerful", "topic": "Jesus and the Lord's Prayer"},
  {"id": 73, "text": "Jesus called God 'my Father' in a unique sense. Through faith and baptism into Christ, believers also become God's children. Jesus distinguished his relationship from ours when he spoke of 'my Father, and your Father' (John 20:17). Remembering our adoption helps us approach God with reverence and gratitude.", "source": "Adapted from John H. Morris — The Path of Prayer", "topic": "Jesus and the Lord's Prayer"},
  {"id": 74, "text": "Praying in Jesus' name is more than adding a familiar phrase to the end of a prayer. It is approaching God through Christ, identifying ourselves with him and seeking to bring our requests into harmony with his spirit and teaching.", "source": "Adapted from David Bailey — Talking with God", "topic": "Jesus and the Lord's Prayer"},
  {"id": 75, "text": "Jesus perfectly lived a life of devotion to God. As Ephesians 5:2 describes, he gave himself as an offering and sacrifice. His entire life expressed obedience to the Father. Prayer should likewise be reflected in the whole direction of our lives.", "source": "Adapted from John H. Morris — The Path of Prayer", "topic": "Jesus and the Lord's Prayer"},
  {"id": 76, "text": "When we review our private prayers, we may discover familiar phrases, subjects and a fixed order. Repetition is not always wrong, but it can make prayer mechanical. The answer is not simply to expand our vocabulary; it is to consider what we truly want to say to God.", "source": "Adapted from David Bailey — Talking with God", "topic": "Sincerity and humility"},
  {"id": 77, "text": "Prayer takes many forms. There are private prayers of confession, brief cries for urgent help, spontaneous thanks for blessings and longer moments of reflection on God's goodness. Each can be sincere and acceptable. No single length or style is required for every circumstance.", "source": "Adapted from H. P. Mansfield — Making Prayer Powerful", "topic": "Sincerity and humility"},
  {"id": 78, "text": "God's forgiveness calls for genuine repentance, and our willingness to forgive others reveals whether we have understood His mercy. Jesus emphasized forgiving from the heart, not merely saying that a grievance has been forgotten.", "source": "Adapted from Greg Palmer — Thoughts on the Lord’s Prayer", "topic": "Sincerity and humility"},
  {"id": 79, "text": "We can pray in sudden trouble and in moments of relief. God invites us to pour out our hearts to Him, so we need not dismiss a concern simply because it seems too personal. What matters is bringing it honestly before Him.", "source": "Adapted from H. P. Mansfield — Making Prayer Powerful", "topic": "Sincerity and humility"},
  {"id": 80, "text": "Of all the subjects in the Lord's Prayer, Jesus especially emphasized forgiveness. If we seek our Father's mercy, we must also be willing to forgive those who have wronged us, sincerely and from the heart.", "source": "Adapted from California Youth Conference 2017 — The Principles and Power of Prayer", "topic": "Sincerity and humility"},
  {"id": 81, "text": "We can acknowledge our failures honestly before God and seek His forgiveness and help. Sincerity does not require us to pretend we are without fault; it calls us to recognize our weakness and desire to change.", "source": "Adapted from H. P. Mansfield — Making Prayer Powerful", "topic": "Sincerity and humility"},
  {"id": 82, "text": "Meditation on God's Word helps us know Him better. When Scripture fills our thoughts, our prayers can become more specific, sincere and grounded in His character and promises.", "source": "Adapted from David Bailey — Talking with God", "topic": "Sincerity and humility"},
  {"id": 83, "text": "Through the covenant in Christ, God calls us to belong to Him. But that relationship should be reflected in the way we live. Our prayers ought to come from a character being shaped by His Word—loyal, sincere and devoted to Him.", "source": "Adapted from David Bailey — Talking with God", "topic": "Sincerity and humility"},
  {"id": 84, "text": "God's Word can help overcome common problems in prayer: distraction, clichés, repetitive subjects and mechanical language. Think of occasions when your prayers were especially heartfelt. Often they followed a meaningful Bible reading, class or personal study that made you more conscious of God.", "source": "Adapted from David Bailey — Talking with God", "topic": "Sincerity and humility"},
  {"id": 85, "text": "Recognizing our unworthiness should lead to humility, not to the belief that our lives have no value. Confession can become a hopeful request for forgiveness and for help to serve God more faithfully.", "source": "Adapted from Melva Purkis and Cyril Tennant — Prayer: Studies in Principle and Practice", "topic": "Sincerity and humility"},
  {"id": 86, "text": "David's prayers are both personal and reverent. They spring from a humbled, repentant heart, but they are also grounded in his knowledge of God's character. Even private prayer can be enriched by Scripture and careful thought.", "source": "Adapted from David Bailey — Talking with God", "topic": "Sincerity and humility"},
  {"id": 87, "text": "Outward displays of devotion are no substitute for sincere repentance. The prophets challenged Israel to change their hearts, not merely their religious behavior. Prayer becomes empty when our conduct contradicts what we say before God.", "source": "Adapted from H. P. Mansfield — Making Prayer Powerful", "topic": "Sincerity and humility"},
  {"id": 88, "text": "Recognizing our weakness can expose habitual prayers that have become empty. Yet humility can also make prayer deeper, helping us speak from genuine need rather than a sense of entitlement.", "source": "Adapted from Melva Purkis and Cyril Tennant — Prayer: Studies in Principle and Practice", "topic": "Sincerity and humility"},
  {"id": 89, "text": "Fervent prayer comes from an earnest heart, regardless of our posture or circumstances. It leaves little room for pride or for trying to impress the people who hear us. Our attention should be on God, not on our audience.", "source": "Adapted from Melva Purkis and Cyril Tennant — Prayer: Studies in Principle and Practice", "topic": "Sincerity and humility"},
  {"id": 90, "text": "We do not always know how to put our deepest needs into words. Our understanding may be limited and our hearts burdened by failure, yet we can still approach God. Our inability to speak perfectly should not prevent sincere prayer.", "source": "Adapted from Melva Purkis and Cyril Tennant — Prayer: Studies in Principle and Practice", "topic": "Sincerity and humility"},
  {"id": 91, "text": "Our prayers must agree with the way we live. Fine words and faithful routines cannot make up for neglecting responsibilities taught in God's Word. What we ask of Him should be supported by a genuine effort to obey Him.", "source": "Adapted from David Bailey — Talking with God", "topic": "Sincerity and humility"},
  {"id": 92, "text": "Prayer requires discipline: learning to turn the mind toward God. Without that effort, even a regular habit can become the mechanical repetition of familiar words. The goal is not simply to 'say our prayers,' but to commune with Him.", "source": "Adapted from H. P. Mansfield — Making Prayer Powerful", "topic": "Consistency and time"},
  {"id": 93, "text": "Because temptation is a constant reality, our awareness of God should not be occasional. Prayer can help us resist sin by bringing His will to mind at the moments when choices are most difficult.", "source": "Adapted from Melva Purkis and Cyril Tennant — Prayer: Studies in Principle and Practice", "topic": "Consistency and time"},
  {"id": 94, "text": "James warns against approaching God without faith. We should pray with confidence in God's character and promises rather than treat prayer as an experiment to discover whether He exists. Faith does not mean knowing in advance how God will answer.", "source": "Adapted from David Bailey — Talking with God", "topic": "Faith and God's Will"},
  {"id": 95, "text": "Looking back, we may recognize moments of unexpected help and care. Such memories can prompt gratitude, but we should not claim to know with certainty why every event happened. Remembering thankfully and interpreting humbly can go together.", "source": "Adapted from John H. Morris — The Path of Prayer", "topic": "Faith and God's Will"},
  {"id": 96, "text": "Prayer deserves a regular place in our lives. Work and responsibilities may be demanding, but none of us can afford to treat communion with God as unnecessary. The challenge is to make meaningful time for it, even during busy seasons.", "source": "Adapted from H. P. Mansfield — Making Prayer Powerful", "topic": "Consistency and time"},
  {"id": 97, "text": "'Pray without ceasing' does not mean spending every waking moment on our knees. Our circumstances differ, but we can develop minds that return regularly to spiritual things and remain conscious of God's presence throughout the day.", "source": "Adapted from John H. Morris — The Path of Prayer", "topic": "Consistency and time"},
  {"id": 98, "text": "Under the Law of Moses, the offering of incense was associated with appointed times of prayer. Morning and evening worship reminded Israel to approach God regularly. The image of rising incense also helps us picture prayer as an offering before Him.", "source": "Adapted from H. P. Mansfield — Making Prayer Powerful", "topic": "Consistency and time"},
  {"id": 99, "text": "David spoke of praying evening, morning and noon (Psalm 55:17). His example encourages a regular pattern of prayer and reminds us that time spent reflecting on God's Word can prepare our hearts to speak to Him.", "source": "Adapted from David Bailey — Talking with God", "topic": "Consistency and time"},
  {"id": 100, "text": "We all develop familiar expressions in everyday speech and in prayer. Even meaningful, scriptural phrases can be repeated without thought. It is worth pausing to consider what our customary words mean before we use them again.", "source": "Adapted from David Bailey — Talking with God", "topic": "Consistency and time"},
  {"id": 101, "text": "Regular times of prayer are valuable, but prayer should not be limited to a schedule. Alongside habitual morning or evening devotion, we can speak to God in sudden need, gratitude or concern. A routine should support genuine prayer, not turn it into empty formality.", "source": "Adapted from H. P. Mansfield — Making Prayer Powerful", "topic": "Consistency and time"},
  {"id": 102, "text": "In Gethsemane Jesus prayed, 'Thy will be done,' even though he deeply desired another outcome. We should also submit our requests to God's wisdom. Prayer is not an attempt to persuade the Father to abandon His purpose in favor of our preferences.", "source": "Adapted from John H. Morris — The Path of Prayer", "topic": "Jesus and the Lord's Prayer"},
  {"id": 103, "text": "Spontaneous prayer is not automatically more sincere than prepared prayer. Without some thought, it can become rambling, repetitive or difficult for others to follow. Preparation can help us speak clearly and reverently while still praying from the heart.", "source": "Adapted from David Bailey — Talking with God", "topic": "Consistency and time"},
  {"id": 104, "text": "Jesus' prayers were never casual or indifferent. Whether praying publicly or alone through the night, he was conscious of his need for his Father's help. His earnest example reminds us that sincerity matters more than outward form.", "source": "Adapted from Melva Purkis and Cyril Tennant — Prayer: Studies in Principle and Practice", "topic": "Consistency and time"},
  {"id": 105, "text": "A habit of prayer in ordinary circumstances helps prepare us for exceptional difficulties. If we rarely turn to God when life is peaceful, we may struggle to do so when a crisis comes. Regular prayer nurtures confidence and familiarity in approaching Him.", "source": "Adapted from Melva Purkis and Cyril Tennant — Prayer: Studies in Principle and Practice", "topic": "Consistency and time"},
  {"id": 106, "text": "Some Psalms read almost like meditations, yet their reflections lead the mind toward God. As we read them, we learn that thinking carefully about His works, character and promises can become part of our communion with Him.", "source": "Adapted from John H. Morris — The Path of Prayer", "topic": "Meditation and Scripture"},
  {"id": 107, "text": "Meditation prepares us for prayer. It helps quiet angry or distracting thoughts, disciplines the mind and gives us something meaningful to bring before God. We need not worry about finding impressive words when our hearts are engaged with His Word.", "source": "Adapted from John H. Morris — The Path of Prayer", "topic": "Meditation and Scripture"},
  {"id": 108, "text": "Prayer is the lifting of heart, mind and will to God. As children, we may think mainly of asking Him for things. With greater understanding of His Word, our prayers can grow to include worship, gratitude, repentance and a desire to do His will.", "source": "Adapted from Melva Purkis and Cyril Tennant — Prayer: Studies in Principle and Practice", "topic": "Meditation and Scripture"},
  {"id": 109, "text": "God's Word teaches us what we truly need, exposes our failings and helps us recognize our dependence upon Him. These reflections can stir feelings too deep for easy expression, giving substance to prayer even when words are difficult.", "source": "Adapted from H. P. Mansfield — Making Prayer Powerful", "topic": "Meditation and Scripture"},
  {"id": 110, "text": "If your thoughts wander during private prayer, try speaking a few sentences aloud. Putting thoughts into words can reveal when a request is vague or repetitive. It is not a rule for how to pray, but a practical aid to concentration.", "source": "Adapted from John H. Morris — The Path of Prayer", "topic": "Meditation and Scripture"},
  {"id": 111, "text": "Reflecting on God's works prepares us to speak to Him. Meditation and prayer can flow back and forth: a thought about His goodness leads to thanksgiving, and a remembered promise leads to a request for help.", "source": "Adapted from John H. Morris — The Path of Prayer", "topic": "Meditation and Scripture"},
  {"id": 112, "text": "God's Word awakens us to spiritual realities and helps us see ourselves truthfully. It reveals where we need forgiveness, strength and wisdom. Bible study therefore gives us better reasons and language for prayer.", "source": "Adapted from H. P. Mansfield — Making Prayer Powerful", "topic": "Meditation and Scripture"},
  {"id": 113, "text": "Prayer and practical care belong together. We can ask God to help someone who is ill or troubled while also offering kindness, encouragement and assistance. Praying for others should never become an excuse for neglecting what we can do.", "source": "Adapted from John H. Morris — The Path of Prayer", "topic": "Intercession and community"},
  {"id": 114, "text": "When Paul prayed for believers, he sought specific spiritual blessings such as joy, peace, unity and growth in faith. Our prayers for the ecclesia can be equally thoughtful. Instead of asking only for general blessings, we can consider the particular needs of those for whom we pray.", "source": "Adapted from John H. Morris — The Path of Prayer", "topic": "Intercession and community"},
  {"id": 115, "text": "Without prayer, Bible study can become merely academic, fellowship merely social, and preaching just an activity. Prayer brings our relationship with God into each part of discipleship, and a genuinely prayerful life should lead to action.", "source": "Adapted from Melva Purkis and Cyril Tennant — Prayer: Studies in Principle and Practice", "topic": "Meditation and Scripture"},
  {"id": 116, "text": "We need not begin every prayer with the same words. Scripture gives us many ways to address God, each reflecting His character: Creator, Almighty God, gracious Father. Thoughtful variety can help prevent stale repetition and deepen our reverence.", "source": "Adapted from John H. Morris — The Path of Prayer", "topic": "Meditation and Scripture"},
  {"id": 117, "text": "Some people can pray attentively amid noise, but many need a quiet place. Choosing a setting with fewer distractions can help us concentrate. Even kneeling beside the bed rather than praying while falling asleep may make a difference.", "source": "Adapted from John H. Morris — The Path of Prayer", "topic": "Meditation and Scripture"},
  {"id": 118, "text": "Scripture teaches us to pray through the examples it records. The Psalms, Jesus' prayers and the petitions in the epistles reveal faith, reverence and concern for others. Regular Bible reading can enrich both the content and practice of prayer.", "source": "Adapted from John H. Morris — The Path of Prayer", "topic": "Meditation and Scripture"},
  {"id": 119, "text": "In prayer we bring God's character before our minds and praise Him for what His Word reveals. We remember His blessings, acknowledge our failures and seek forgiveness and strength to overcome our weaknesses.", "source": "Adapted from H. P. Mansfield — Making Prayer Powerful", "topic": "Meditation and Scripture"},
  {"id": 120, "text": "Abraham's prayer for Sodom was urgent, humble and focused on one concern. He did not include every possible element of a formal prayer, yet God heard him. A sincere prayer about one pressing need is not inadequate simply because it is brief.", "source": "Adapted from John H. Morris — The Path of Prayer", "topic": "Sincerity and humility"},
  {"id": 121, "text": "Our prayers naturally begin with personal needs, but they should grow wider as our concern for others deepens. We pray for family, friends, brethren and sisters, ecclesias and the work of the Gospel. Prayer helps us carry the needs of a whole community before God.", "source": "Adapted from John H. Morris — The Path of Prayer", "topic": "Intercession and community"},
  {"id": 122, "text": "It is easy to enjoy food without thinking about the One who ultimately provides it. Even when we give thanks, familiar words can become little more than habit. We should pause to recognize our dependence upon God and respond with genuine gratitude.", "source": "Adapted from Greg Palmer — Thoughts on the Lord’s Prayer", "topic": "Praise and thanksgiving"},
  {"id": 123, "text": "Nehemiah prayed briefly and silently under pressure. Hannah prayed with heartfelt conviction even when others misunderstood her. Their examples remind us that prayer is addressed to God, whether others hear our words or not.", "source": "Adapted from California Youth Conference 2017 — The Principles and Power of Prayer", "topic": "Sincerity and humility"},
  {"id": 124, "text": "We should examine whether our requests are sincere or merely formal. It is possible to repeat familiar petitions without really desiring the outcome or believing God can answer. Honest self-examination can help us make our prayers more thoughtful and earnest.", "source": "Adapted from Harry Whittaker — Prayer", "topic": "Sincerity and humility"},
  {"id": 125, "text": "Prayers recorded in Israel's history often name a particular difficulty, remember the people affected and make a specific request. Their example can help us move beyond vague expressions and pray thoughtfully about real needs.", "source": "Adapted from California Youth Conference 2017 — The Principles and Power of Prayer", "topic": "Intercession and community"},
  {"id": 126, "text": "Forgiveness is vital to our fellowship with God. Our need for mercy should make us more aware of how we treat others, because receiving forgiveness and offering it are closely connected in the teaching of Jesus.", "source": "Adapted from Melva Purkis and Cyril Tennant — Prayer: Studies in Principle and Practice", "topic": "Sincerity and humility"},
  {"id": 127, "text": "Nehemiah prayed, then appointed a watch. He did not regard prayer as a way to escape his responsibilities. He trusted that deliverance came from God while recognizing that God might use the efforts of His people to accomplish it.", "source": "Adapted from Melva Purkis and Cyril Tennant — Prayer: Studies in Principle and Practice", "topic": "Intercession and community"},
  {"id": 128, "text": "When danger or crisis strikes, it is natural to feel helpless and seek God's aid. That instinct is not cowardice. Prayer brings our fears and limitations honestly before the One whose wisdom and strength exceed our own.", "source": "Adapted from Harry Whittaker — Prayer", "topic": "Trials and unanswered prayer"},
  {"id": 129, "text": "When the ecclesia prays for someone who is suffering, it is not merely taking over that person's responsibility to pray. It is standing alongside them in intercession. Shared prayer can express compassion and strengthen the fellowship of believers.", "source": "Adapted from Melva Purkis and Cyril Tennant — Prayer: Studies in Principle and Practice", "topic": "Intercession and community"},
  {"id": 130, "text": "Nehemiah's life was marked by prayer. Again and again, in the middle of difficult tasks or sudden decisions, he turned to God. His spontaneous prayers show how naturally devotion can become part of active service.", "source": "Adapted from Melva Purkis and Cyril Tennant — Prayer: Studies in Principle and Practice", "topic": "Intercession and community"},
  {"id": 131, "text": "Moses' prayers for Israel did not always obtain the result he sought. If even such a faithful intercessor experienced disappointment, we should not suppose that every earnest petition will be granted as we wish. Nevertheless, God's promised purpose remains sure, and the hope before us is not lost.", "source": "Adapted from Harry Whittaker — Prayer", "topic": "Trials and unanswered prayer"},
  {"id": 132, "text": "Hannah's distress did not drive her away from worship. Though burdened with sorrow, she remained with her family and poured out her heart in prayer. Her example shows that deep personal pain can be brought openly before God.", "source": "Adapted from Harry Whittaker — Prayer", "topic": "Trials and unanswered prayer"},
  {"id": 133, "text": "Prayer acknowledges our weakness and God's power, but it reaches beyond seeking personal relief. It can draw our attention to His purpose, deepen our commitment to Him and help us see everyday concerns in the light of eternal hope.", "source": "Adapted from Melva Purkis and Cyril Tennant — Prayer: Studies in Principle and Practice", "topic": "Privilege and purpose"},
  {"id": 134, "text": "Intercession grows from confidence in the goodness of the One to whom we appeal. It is especially meaningful when our request is unselfish and arises from genuine concern for someone else's welfare.", "source": "Adapted from Harry Whittaker — Prayer", "topic": "Intercession and community"},
  {"id": 135, "text": "Nehemiah did not begin his work for Jerusalem with a plan alone. He first mourned, fasted and prayed, confessing Israel's failures and recalling God's promises. His example encourages us to bring a concern before God thoughtfully before deciding how to act.", "source": "Adapted from Melva Purkis and Cyril Tennant — Prayer: Studies in Principle and Practice", "topic": "Intercession and community"},
  {"id": 136, "text": "As we learn more about Jesus' words and example, our desires can become better aligned with God's will. Prayer is not only about asking Him to change our circumstances; it also helps us examine the direction of our own lives.", "source": "Adapted from Melva Purkis and Cyril Tennant — Prayer: Studies in Principle and Practice", "topic": "Trials and unanswered prayer"},
  {"id": 137, "text": "We often find it easier to pray when we can imagine a way out of difficulty. But when every human solution seems closed, faith is truly tested. God's ability to help is not limited to the possibilities we can see.", "source": "Adapted from Melva Purkis and Cyril Tennant — Prayer: Studies in Principle and Practice", "topic": "Trials and unanswered prayer"},
  {"id": 138, "text": "James reminds us that Elijah was a person with a nature like ours. His example shows that earnest prayer is not reserved for extraordinary people. Ordinary believers can also turn to God with faith and persistence.", "source": "Adapted from Melva Purkis and Cyril Tennant — Prayer: Studies in Principle and Practice", "topic": "Trials and unanswered prayer"},
  {"id": 139, "text": "Faith is essential to prayer, but we need not wait until our trust feels perfect. We can bring our imperfect understanding before God and seek to grow in confidence as we remember His character and promises.", "source": "Adapted from Melva Purkis and Cyril Tennant — Prayer: Studies in Principle and Practice", "topic": "Trials and unanswered prayer"},
  {"id": 140, "text": "The ecclesia prayed earnestly for Peter's release, yet struggled to believe when he was freed. Paul prayed repeatedly for his thorn in the flesh to be removed, but the answer was no. These examples show that God's answers do not always fit our expectations.", "source": "Adapted from Harry Whittaker — Prayer", "topic": "Trials and unanswered prayer"},
  {"id": 141, "text": "Prayer should never be merely casual. When we bring a request to God, it should matter to us. Scripture illustrates persistence through the widow, Elijah and above all Jesus, whose prayers were offered with deep feeling and earnestness.", "source": "Adapted from Melva Purkis and Cyril Tennant — Prayer: Studies in Principle and Practice", "topic": "Trials and unanswered prayer"},
  {"id": 142, "text": "Abraham, Hannah and Zacharias all waited for things they deeply desired. Zacharias eventually heard the words, 'Thy prayer is heard.' Their experiences remind us that waiting can test faith, but a delay does not by itself mean that God has failed to hear.", "source": "Adapted from Harry Whittaker — Prayer", "topic": "Trials and unanswered prayer"},
  {"id": 143, "text": "A brief prayer with carefully chosen words may express more than a long prayer filled with repeated phrases. Whether praying alone or with others, aim to make the praise, confession or request clear and sincere rather than stretching the prayer to a particular length.", "source": "Adapted from Harry Whittaker — Prayer", "topic": "Sincerity and humility"},
  {"id": 144, "text": "Recall occasions when you recognized God's care in your life. Such memories can strengthen your faith in a present emergency. If you struggle to think of examples, reflect on the blessings and guidance you may have overlooked.", "source": "Adapted from Harry Whittaker — Prayer", "topic": "Trials and unanswered prayer"},
  {"id": 145, "text": "In Gethsemane Jesus asked that the cup might pass from him, yet submitted to his Father's will. The cup did not pass, because his suffering was bound up with God's purpose of redemption. Even the most faithful prayer does not guarantee the answer we desire.", "source": "Adapted from Harry Whittaker — Prayer", "topic": "Trials and unanswered prayer"},
  {"id": 146, "text": "Scripture gives us freedom to pray earnestly, even repeatedly, for healing and relief. Yet such requests should spring from right motives and trust in God's wisdom, not from an expectation that He must grant exactly what we ask.", "source": "Adapted from Harry Whittaker — Prayer", "topic": "Trials and unanswered prayer"},
  {"id": 147, "text": "Scripture records people praying while kneeling, sitting, standing and lying prostrate. No single posture guarantees reverence. We should choose a position that helps us concentrate and show respect, while remembering that God is concerned with the heart.", "source": "Adapted from Harry Whittaker — Prayer", "topic": "Sincerity and humility"},
  {"id": 148, "text": "Illness and suffering often lead people to seek God's help. Believers may rightly ask for healing or relief, while remembering that the Father's wisdom governs the answer. Prayer during sickness expresses dependence and hope, not a guarantee of immediate recovery.", "source": "Adapted from Harry Whittaker — Prayer", "topic": "Trials and unanswered prayer"},
  {"id": 149, "text": "David's Psalms show how physical suffering can become a reason to seek God with greater earnestness. When another person is ill, we should not presume to know the cause or God's purpose. Compassion, practical care and humble prayer are more fitting responses.", "source": "Adapted from Harry Whittaker — Prayer", "topic": "Trials and unanswered prayer"},
  {"id": 150, "text": "Children seek a father's help in different ways. One may ask quietly; another may cry urgently. Both depend on the same loving parent. Believers also express faith and need differently as they turn to their Heavenly Father.", "source": "Adapted from Harry Whittaker — Prayer", "topic": "Trials and unanswered prayer"},
];
